#!/usr/bin/env python3
"""Generate the PlatformIO library -> dependents map from the firmware tree.

`library_dependents` in .github/firmware-platformio-impact.json is derived, not
hand-written: every entry is computed from the `lib_deps` of each
Firmware/**/platformio.ini plus the `dependencies` each
Firmware/Libraries/*/library.json declares. Hand-maintaining it drifted badly —
it listed a non-existent Firmware/Prototype/ tree, had no NodeStatus key at all,
and under-listed A4EC 2-of-9 — so CI regenerates and compares instead.

    --write   rewrite the map in place
    --check   exit 1 if the committed map differs from a fresh scan (CI)

`full_build_paths` is hand-maintained and is preserved verbatim by --write.
"""

from __future__ import annotations

import argparse
import configparser
import difflib
import json
import sys
from pathlib import Path


GENERATED_NOTE = (
    "library_dependents is generated by .github/scripts/gen-platformio-impact-map.py "
    "-- run it with --write instead of editing that map by hand."
)


def repo_root() -> Path:
    return Path(__file__).resolve().parents[2]


def map_path(root: Path) -> Path:
    return root / ".github" / "firmware-platformio-impact.json"


def libraries(root: Path) -> list[str]:
    lib_root = root / "Firmware" / "Libraries"
    return sorted(p.name for p in lib_root.iterdir() if p.is_dir())


def local_library(token: str, known: set[str]) -> str | None:
    """Resolve one lib_deps token to a local library name, or None.

    Three forms appear in this tree:
      file://../../Libraries/PanelGroup   -> local, by path
      PanelGroup                          -> local, by bare name (lib_extra_dirs)
      adafruit/Adafruit ADS1X15@^2.0.0    -> third party, ignored
    """
    token = token.strip()
    if not token:
        return None

    if token.startswith("file://"):
        name = Path(token[len("file://") :]).name
    elif "/" in token:
        return None  # owner/name -> registry package
    else:
        name = token

    name = name.split("@")[0].strip()
    return name if name in known else None


def project_libraries(ini: Path, known: set[str]) -> set[str]:
    """Local libraries a project declares, unioned over every section.

    The union is deliberate: these projects put lib_deps on a shared [env_base]
    that each [env:*] pulls in via `extends`, and CI builds every env anyway.
    interpolation=None because the files use ${PROJECT_DIR} and ${sysenv.HOME},
    which ConfigParser's default interpolation rejects.
    """
    parser = configparser.ConfigParser(strict=False, interpolation=None)
    parser.read(ini, encoding="utf-8")

    found: set[str] = set()
    for section in parser.sections():
        if not parser.has_option(section, "lib_deps"):
            continue
        for line in parser.get(section, "lib_deps").splitlines():
            name = local_library(line, known)
            if name:
                found.add(name)
    return found


def library_edges(root: Path, known: set[str]) -> dict[str, set[str]]:
    """library -> local libraries it depends on, from each library.json."""
    edges: dict[str, set[str]] = {}
    for lib in sorted(known):
        manifest = root / "Firmware" / "Libraries" / lib / "library.json"
        found: set[str] = set()
        if manifest.exists():
            declared = json.loads(manifest.read_text(encoding="utf-8")).get("dependencies", {})
            tokens = (
                declared.keys()
                if isinstance(declared, dict)
                else [d.get("name", "") if isinstance(d, dict) else d for d in declared]
            )
            for token in tokens:
                name = local_library(str(token), known)
                if name:
                    found.add(name)
        edges[lib] = found
    return edges


def closure(seeds: set[str], edges: dict[str, set[str]]) -> set[str]:
    """Every library reachable from `seeds`, following library.json deps.

    A project that lists only PanelGroup still compiles CANProtocol and
    STM32Board, so a change to either must select that project.
    """
    seen: set[str] = set()
    pending = list(seeds)
    while pending:
        current = pending.pop()
        if current in seen:
            continue
        seen.add(current)
        pending.extend(edges.get(current, ()))
    return seen


def discover_projects(root: Path) -> list[str]:
    """Mirror select-platformio-projects.py: every platformio.ini bar ScratchPad."""
    projects: list[str] = []
    for ini in (root / "Firmware").rglob("platformio.ini"):
        rel = ini.relative_to(root)
        if "ScratchPad" in rel.parts:
            continue
        projects.append(rel.parent.as_posix())
    return sorted(projects)


def build_dependents(root: Path) -> dict[str, list[str]]:
    known = set(libraries(root))
    edges = library_edges(root, known)

    dependents: dict[str, set[str]] = {lib: set() for lib in known}
    for project in discover_projects(root):
        declared = project_libraries(root / project / "platformio.ini", known)
        for lib in closure(declared, edges):
            dependents[lib].add(project)

    return {lib: sorted(dependents[lib]) for lib in sorted(dependents)}


def render(root: Path) -> str:
    existing = json.loads(map_path(root).read_text(encoding="utf-8"))
    document = {
        "_generated": GENERATED_NOTE,
        "full_build_paths": existing.get("full_build_paths", []),
        "library_dependents": build_dependents(root),
    }
    return json.dumps(document, indent=2) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser()
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--write", action="store_true", help="rewrite the map in place")
    group.add_argument("--check", action="store_true", help="fail if the map is stale")
    args = parser.parse_args()

    root = repo_root()
    target = map_path(root)
    generated = render(root)

    if args.write:
        target.write_text(generated, encoding="utf-8")
        print(f"Wrote {target.relative_to(root)}")
        return 0

    committed = target.read_text(encoding="utf-8")
    if committed == generated:
        print(f"{target.relative_to(root)} is up to date.")
        return 0

    print(f"{target.relative_to(root)} is stale — regenerate it:", file=sys.stderr)
    print("    python3 .github/scripts/gen-platformio-impact-map.py --write\n", file=sys.stderr)
    sys.stderr.writelines(
        difflib.unified_diff(
            committed.splitlines(keepends=True),
            generated.splitlines(keepends=True),
            fromfile="committed",
            tofile="generated",
        )
    )
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
